import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.math.*;
import java.io.IOException;

final class ModelIo {
    static final class Model {
        String name;
        char[] states, symbols;
        char missing;
        double[] pi;
        double[][] a, b;
        Model(String name, char[] states, char[] symbols, char missing, double[] pi, double[][] a,
              double[][] b) {
            this.name = name;
            this.states = states;
            this.symbols = symbols;
            this.missing = missing;
            this.pi = normalize(pi);
            this.a = new double[a.length][];
            this.b = new double[b.length][];
            for (int i = 0; i < a.length; i++)
                this.a[i] = normalize(a[i]);
            for (int i = 0; i < b.length; i++)
                this.b[i] = normalize(b[i]);
        }
    }
    record Data(Model model, List<String> sequences, List<String> labeled, Map<String, String[]> params) {}
    static double[] normalize(double[] values) {
        double sum = 0;
        for (double value : values)
            sum += value;
        double[] result = new double[values.length];
        for (int i = 0; i < values.length; i++)
            result[i] = values[i] / sum;
        return result;
    }
    static List<String> lines(String name) throws IOException {
        return Files.readAllLines(Path.of("input", name), StandardCharsets.US_ASCII);
    }
    static double[] numbers(String[] words, int start) {
        double[] result = new double[words.length - start];
        for (int i = start; i < words.length; i++)
            result[i - start] = Double.parseDouble(words[i]);
        return result;
    }
    static char[] letters(String line) {
        String[] w = line.split(" ");
        char[] result = new char[w.length - 1];
        for (int i = 1; i < w.length; i++)
            result[i - 1] = w[i].charAt(0);
        return result;
    }
    static Data read() throws IOException {
        List<String> input = lines("model.txt");
        char[] states = letters(input.get(0)), symbols = letters(input.get(1));
        char missing = input.get(2).split(" ")[1].charAt(0);
        int k = states.length;
        double[] pi = numbers(input.get(3).split(" "), 1);
        double[][] a = new double[k][], b = new double[k][];
        for (int i = 0; i < k; i++) {
            a[i] = numbers(input.get(4 + i).split(" "), 2);
            b[i] = numbers(input.get(4 + k + i).split(" "), 2);
        }
        Map<String, String[]> params = new HashMap<>();
        for (String line : lines("params.txt")) {
            String[] words = line.split(" ");
            params.put(words[0], Arrays.copyOfRange(words, 1, words.length));
        }
        return new Data(new Model("INITIAL", states, symbols, missing, pi, a, b), lines("sequences.txt"),
                        lines("labeled.txt"), params);
    }
    static String real(double value, int digits) {
        if (Double.isNaN(value))
            return "-";
        BigDecimal result = BigDecimal.valueOf(value).setScale(digits, RoundingMode.HALF_UP);
        if (result.signum() == 0)
            result = BigDecimal.ZERO.setScale(digits);
        return result.toPlainString();
    }
    static String f(double value) {
        return real(value, 4);
    }
    static String values(double[] values) {
        String text = "";
        for (double value : values)
            text += " " + f(value);
        return text;
    }
    static String names(char[] names) {
        String text = "";
        for (char name : names)
            text += " " + name;
        return text;
    }
    static List<String> format(Model model) {
        List<String> out = new ArrayList<>(List.of("MODEL " + model.name, "STATES" + names(model.states),
                                                   "SYMBOLS" + names(model.symbols),
                                                   "MISSING " + model.missing, "INITIAL" + values(model.pi)));
        for (int i = 0; i < model.states.length; i++)
            out.add("TRANSITION " + model.states[i] + values(model.a[i]));
        for (int i = 0; i < model.states.length; i++)
            out.add("EMISSION " + model.states[i] + values(model.b[i]));
        return out;
    }
    static void write(String name, List<String> lines) throws IOException {
        Files.writeString(Path.of("output", name), String.join("\n", lines) + "\n",
                          StandardCharsets.US_ASCII);
    }
}

final class Sampler {
    static final class Random {
        long state;
        Random(long seed) {
            state = seed;
        }
        double next() {
            state = 48271 * state % 2147483647;
            return state / 2147483647.0;
        }
    }
    record Synthetic(int[] states, int[] observations) {}
    static int draw(double[] weights, Random random) {
        double total = 0;
        for (double weight : weights)
            total += weight;
        double threshold = random.next() * total, cumulative = 0;
        for (int i = 0; i < weights.length; i++) {
            cumulative += weights[i];
            if (threshold < cumulative)
                return i;
        }
        return weights.length - 1;
    }
    static Synthetic synthetic(ModelIo.Model model, int length, Random random) {
        int[] states = new int[length], observations = new int[length];
        for (int t = 0; t < length; t++) {
            states[t] = draw(t == 0 ? model.pi : model.a[states[t - 1]], random);
            observations[t] = draw(model.b[states[t]], random);
        }
        return new Synthetic(states, observations);
    }
    static int[] posterior(ModelIo.Model model, double[][] forward, Random random) {
        int[] path = new int[forward.length];
        path[path.length - 1] = draw(forward[path.length - 1], random);
        for (int t = path.length - 2; t >= 0; t--) {
            double[] weights = new double[model.states.length];
            for (int i = 0; i < weights.length; i++)
                weights[i] = forward[t][i] * model.a[i][path[t + 1]];
            path[t] = draw(weights, random);
        }
        return path;
    }
}

import java.util.*;

final class Training {
    record Pair(int[] observations, int[] path) {}
    static ModelIo.Model smooth(ModelIo.Model template, String name, double[] pi, double[][] a, double[][] b,
                                double alpha) {
        for (int i = 0; i < pi.length; i++) {
            pi[i] += alpha;
            for (int j = 0; j < a[i].length; j++)
                a[i][j] += alpha;
            for (int c = 0; c < b[i].length; c++)
                b[i][c] += alpha;
        }
        return new ModelIo.Model(name, template.states, template.symbols, template.missing, pi, a, b);
    }
    static ModelIo.Model baumWelch(ModelIo.Model model, List<int[]> sequences, double alpha) {
        int k = model.states.length, m = model.symbols.length;
        double[] pi = new double[k];
        double[][] a = new double[k][k], b = new double[k][m];
        for (int[] observations : sequences) {
            Inference.Fb fb = Inference.backward(model, observations);
            for (int i = 0; i < k; i++)
                pi[i] += fb.gamma()[0][i];
            for (int t = 0; t < observations.length; t++)
                for (int i = 0; i < k; i++) {
                    if (observations[t] >= 0)
                        b[i][observations[t]] += fb.gamma()[t][i];
                    if (t + 1 < observations.length)
                        for (int j = 0; j < k; j++)
                            a[i][j] += Inference.xi(model, fb, t, i, j);
                }
        }
        return smooth(model, "BAUM_WELCH", pi, a, b, alpha);
    }
    static ModelIo.Model count(ModelIo.Model template, List<Pair> pairs, double alpha, String name) {
        int k = template.states.length, m = template.symbols.length;
        double[] pi = new double[k];
        double[][] a = new double[k][k], b = new double[k][m];
        for (Pair pair : pairs) {
            int[] path = pair.path(), observations = pair.observations();
            pi[path[0]]++;
            for (int t = 0; t < path.length; t++) {
                if (observations[t] >= 0)
                    b[path[t]][observations[t]]++;
                if (t + 1 < path.length)
                    a[path[t]][path[t + 1]]++;
            }
        }
        return smooth(template, name, pi, a, b, alpha);
    }
    static double loglik(ModelIo.Model model, List<int[]> sequences) {
        double sum = 0;
        for (int[] observations : sequences)
            sum += Inference.forward(model, observations).loglik();
        return sum;
    }
}
